using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace SoulPilates.Core.Entities;

/// <summary>
/// A screenshot of a Google review that a receptionist received and uploaded,
/// attributed to that receptionist and assigned to a calendar month. The month's
/// total upload count feeds the receptionist-KPI "Google reviews" metric additively
/// (on top of the admin-entered manual count — see <see cref="ReceptionistKpiMonthOverride.GoogleReviewCount"/>).
/// Image bytes live in object storage (RustFS/S3) via <c>IMediaStorage</c>; only the
/// storage key + public URL are persisted here.
/// </summary>
public class ReviewUpload : BaseEntity
{
    /// <summary>The receptionist this review is credited to.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>Staff display name captured at upload time (survives later renames).</summary>
    public string StaffNameSnapshot { get; set; } = string.Empty;

    // ── Period the review is assigned to ─────────────────────────
    public int Year { get; set; }
    public int Month { get; set; }

    // ── Stored image (via IMediaStorage) ─────────────────────────
    /// <summary>Deterministic storage key, e.g. "review-uploads/{id}.webp".</summary>
    public string ImageKey { get; set; } = string.Empty;
    /// <summary>Absolute public URL resolved from the key.</summary>
    public string ImageUrl { get; set; } = string.Empty;

    // ── Optional metadata ────────────────────────────────────────
    public string? ReviewerName { get; set; }
    /// <summary>Optional 1–5 star rating, if the receptionist records it.</summary>
    public int? Rating { get; set; }
    public string? Notes { get; set; }

    /// <summary>The date/time the image was added (the "added-date" shown in the gallery).</summary>
    public DateTime UploadedAt { get; set; } = DateTime.UtcNow;
}
