using MongoDB.Bson;
using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Receptionist-uploaded Google-review screenshots. Images go through the shared
/// <see cref="IMediaStorage"/> pipeline (decode → EXIF-strip → resize → WebP) exactly
/// like class/instructor photos; only the resulting key + URL are stored on the record.
/// </summary>
public class ReviewUploadService : IReviewUploadService
{
    private const string KeyPrefix = "review-uploads";

    private readonly IMongoCollection<ReviewUpload> _uploads;
    private readonly IMongoCollection<Staff> _staff;
    private readonly IMediaStorage _media;

    public ReviewUploadService(MongoDbContext db, IMediaStorage media)
    {
        _uploads = db.GetCollection<ReviewUpload>("ReviewUploads");
        _staff = db.GetCollection<Staff>("Staff");
        _media = media;

        // Fast lookups for the per-staff monthly gallery and the KPI monthly count.
        _uploads.Indexes.CreateOne(new CreateIndexModel<ReviewUpload>(
            Builders<ReviewUpload>.IndexKeys
                .Ascending(x => x.StaffId)
                .Ascending(x => x.Year)
                .Ascending(x => x.Month),
            new CreateIndexOptions { Name = "ix_staff_year_month" }));
        _uploads.Indexes.CreateOne(new CreateIndexModel<ReviewUpload>(
            Builders<ReviewUpload>.IndexKeys
                .Ascending(x => x.Year)
                .Ascending(x => x.Month),
            new CreateIndexOptions { Name = "ix_year_month" }));
    }

    public async Task<ReviewUploadDto> AddAsync(
        string staffId,
        int year,
        int month,
        Stream imageStream,
        string? reviewerName,
        int? rating,
        string? notes,
        CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(staffId))
            throw new InvalidOperationException("Receptionist staff id is required.");
        if (month < 1 || month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");
        if (year < 2000 || year > 2100)
            throw new InvalidOperationException("Year is out of range.");

        var staff = await _staff.Find(s => s.Id == staffId && s.Role == "RECEPTIONIST").FirstOrDefaultAsync(ct)
            ?? throw new InvalidOperationException("Receptionist profile not found.");

        // Deterministic per-record key — generate the id up front so the stored image
        // and the record share it (mirrors the media pattern for entity-owned images).
        var id = ObjectId.GenerateNewId().ToString();
        var key = $"{KeyPrefix}/{id}.webp";

        await _media.UploadImageAsync(imageStream, key, ct: ct);
        var url = _media.PublicUrlFor(key);

        var normalizedRating = rating is >= 1 and <= 5 ? rating : null;

        var row = new ReviewUpload
        {
            Id = id,
            StaffId = staffId,
            StaffNameSnapshot = staff.Name,
            Year = year,
            Month = month,
            ImageKey = key,
            ImageUrl = url,
            ReviewerName = string.IsNullOrWhiteSpace(reviewerName) ? null : reviewerName.Trim(),
            Rating = normalizedRating,
            Notes = string.IsNullOrWhiteSpace(notes) ? null : notes.Trim(),
            UploadedAt = DateTime.UtcNow,
        };

        try
        {
            await _uploads.InsertOneAsync(row, cancellationToken: ct);
        }
        catch
        {
            // Don't leave an orphaned object in storage if the DB write fails.
            await _media.DeleteAsync(key, ct);
            throw;
        }

        return Map(row);
    }

    public async Task<ReviewUploadListDto> ListForStaffMonthAsync(string staffId, int year, int month, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(staffId))
            throw new InvalidOperationException("Receptionist staff id is required.");
        if (month < 1 || month > 12)
            throw new InvalidOperationException("Month must be between 1 and 12.");

        var rows = await _uploads
            .Find(x => x.StaffId == staffId && x.Year == year && x.Month == month)
            .SortByDescending(x => x.UploadedAt)
            .ToListAsync(ct);

        return new ReviewUploadListDto
        {
            Year = year,
            Month = month,
            StaffId = staffId,
            Count = rows.Count,
            Items = rows.Select(Map).ToList(),
        };
    }

    public async Task<bool> DeleteAsync(string id, string? requireStaffId, CancellationToken ct = default)
    {
        var row = await _uploads.Find(x => x.Id == id).FirstOrDefaultAsync(ct);
        if (row is null)
            return false;
        if (!string.IsNullOrWhiteSpace(requireStaffId) && row.StaffId != requireStaffId)
            return false;

        var res = await _uploads.DeleteOneAsync(x => x.Id == id, ct);
        if (res.DeletedCount == 0)
            return false;

        if (!string.IsNullOrWhiteSpace(row.ImageKey))
            await _media.DeleteAsync(row.ImageKey, ct);
        return true;
    }

    public async Task<int> CountForMonthAsync(int year, int month, CancellationToken ct = default)
    {
        var count = await _uploads.CountDocumentsAsync(x => x.Year == year && x.Month == month, cancellationToken: ct);
        return (int)count;
    }

    private static ReviewUploadDto Map(ReviewUpload x) => new()
    {
        Id = x.Id ?? string.Empty,
        StaffId = x.StaffId,
        StaffName = x.StaffNameSnapshot,
        Year = x.Year,
        Month = x.Month,
        ImageUrl = x.ImageUrl,
        ReviewerName = x.ReviewerName,
        Rating = x.Rating,
        Notes = x.Notes,
        UploadedAt = x.UploadedAt,
    };
}

