using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Options;
using SoulPilates.Core.Configuration;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Controllers;

/// <summary>
/// Receptionist-facing Google-review screenshot uploads. A receptionist uploads a photo
/// of a review she received; it's credited to her and assigned to a month. The month's
/// upload count feeds the KPI "Google reviews" metric additively. Admins may view/manage
/// any receptionist's gallery; a receptionist is scoped to her own linked staff profile.
/// </summary>
[ApiController]
[Route("api/review-uploads")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public class ReviewUploadController : ControllerBase
{
    private readonly IReviewUploadService _reviews;
    private readonly StorageSettings _settings;

    public ReviewUploadController(IReviewUploadService reviews, IOptions<StorageSettings> settings)
    {
        _reviews = reviews;
        _settings = settings.Value;
    }

    // ── Upload a review screenshot for a month ──────────────────

    [HttpPost]
    [RequestSizeLimit(15_728_640)] // 15 MB envelope (10 MB image + overhead), matches MediaController
    public async Task<IActionResult> Upload(
        [FromForm] int year,
        [FromForm] int month,
        [FromForm] string? staffId,
        [FromForm] string? reviewerName,
        [FromForm] int? rating,
        [FromForm] string? notes,
        IFormFile file,
        CancellationToken ct)
    {
        var effectiveStaffId = ResolveStaffId(staffId);
        if (string.IsNullOrWhiteSpace(effectiveStaffId))
            return BadRequest(new { message = "This login is not linked to a receptionist staff profile yet." });

        if (!TryValidate(file, out var problem))
            return problem!;

        try
        {
            await using var stream = file.OpenReadStream();
            var dto = await _reviews.AddAsync(effectiveStaffId, year, month, stream, reviewerName, rating, notes, ct);
            return Ok(dto);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── List a receptionist's uploads for a month (gallery) ─────

    [HttpGet]
    public async Task<IActionResult> List(
        [FromQuery] int? year,
        [FromQuery] int? month,
        [FromQuery] string? staffId,
        CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var effectiveStaffId = ResolveStaffId(staffId);
        if (string.IsNullOrWhiteSpace(effectiveStaffId))
            return BadRequest(new { message = "This login is not linked to a receptionist staff profile yet." });

        try
        {
            var dto = await _reviews.ListForStaffMonthAsync(effectiveStaffId, year ?? now.Year, month ?? now.Month, ct);
            return Ok(dto);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    // ── Delete an upload ────────────────────────────────────────

    [HttpDelete("{id}")]
    public async Task<IActionResult> Delete(string id, CancellationToken ct)
    {
        // Admins may delete anyone's; a receptionist may only delete her own.
        var requireStaffId = User.IsInRole("Admin") ? null : ResolveOwnStaffId();
        if (!User.IsInRole("Admin") && string.IsNullOrWhiteSpace(requireStaffId))
            return BadRequest(new { message = "This login is not linked to a receptionist staff profile yet." });

        var deleted = await _reviews.DeleteAsync(id, requireStaffId, ct);
        return deleted ? NoContent() : NotFound(new { message = "Review upload not found." });
    }

    // ── Helpers ─────────────────────────────────────────────────

    /// <summary>Admins may act on an explicit staffId; everyone else is pinned to their own staff profile.</summary>
    private string? ResolveStaffId(string? requestedStaffId)
    {
        if (User.IsInRole("Admin") && !string.IsNullOrWhiteSpace(requestedStaffId))
            return requestedStaffId;
        return ResolveOwnStaffId();
    }

    private string? ResolveOwnStaffId() => User.FindFirst("staff_id")?.Value;

    private bool TryValidate(IFormFile? file, out IActionResult? problem)
    {
        problem = null;

        if (file is null || file.Length == 0)
        {
            problem = BadRequest(new { message = "No file uploaded." });
            return false;
        }

        if (file.Length > _settings.MaxUploadBytes)
        {
            problem = StatusCode(StatusCodes.Status413PayloadTooLarge,
                new { message = $"File exceeds {_settings.MaxUploadBytes / 1_048_576} MB limit." });
            return false;
        }

        var ct = (file.ContentType ?? "").ToLowerInvariant();
        if (ct is not ("image/jpeg" or "image/jpg" or "image/png" or "image/webp" or "image/gif"))
        {
            problem = BadRequest(new { message = $"Unsupported content type '{file.ContentType}'. Use JPEG, PNG, WebP or GIF." });
            return false;
        }

        if (!HasImageMagicBytes(file))
        {
            problem = BadRequest(new { message = "File contents do not appear to be a valid image." });
            return false;
        }

        return true;
    }

    private static bool HasImageMagicBytes(IFormFile file)
    {
        Span<byte> buf = stackalloc byte[12];
        using var s = file.OpenReadStream();
        var read = s.Read(buf);
        if (read < 4) return false;

        // JPEG  FF D8 FF
        if (buf[0] == 0xFF && buf[1] == 0xD8 && buf[2] == 0xFF) return true;
        // PNG   89 50 4E 47
        if (buf[0] == 0x89 && buf[1] == 0x50 && buf[2] == 0x4E && buf[3] == 0x47) return true;
        // GIF   47 49 46 38
        if (buf[0] == 0x47 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x38) return true;
        // WebP  52 49 46 46 …. 57 45 42 50
        if (read >= 12 && buf[0] == 0x52 && buf[1] == 0x49 && buf[2] == 0x46 && buf[3] == 0x46
            && buf[8] == 0x57 && buf[9] == 0x45 && buf[10] == 0x42 && buf[11] == 0x50) return true;
        return false;
    }
}

