197	<script>
198	  const API = import.meta.env.PUBLIC_API_URL;
199	  const token = localStorage.getItem("token");
200	
201	  const monthPicker = document.getElementById("monthPicker");
202	  const staffPicker = document.getElementById("staffPicker");
203	  const staffPickerWrap = document.getElementById("staffPickerWrap");
204	  const fileInput = document.getElementById("fileInput");
205	  const dropzone = document.getElementById("dropzone");
206	  const previewImg = document.getElementById("previewImg");
207	  const dropPrompt = document.getElementById("dropPrompt");
208	  const uploadBtn = document.getElementById("uploadBtn");
209	
210	  let isAdmin = false;
211	  let selectedFile = null;
212	
213	  function parseJwtPayload(rawToken) {
214	    try {
215	      const segment = rawToken?.split(".")?.[1];
216	      if (!segment) return {};
217	      const normalized = segment
218	        .replaceAll("-", "+")
219	        .replaceAll("_", "/")
220	        .padEnd(Math.ceil(segment.length / 4) * 4, "=");
221	      return JSON.parse(atob(normalized));
222	    } catch {
223	      return {};
224	    }
225	  }
226	
227	  function escapeHtml(value) {
228	    return String(value ?? "")
229	      .replaceAll("&", "&amp;")
230	      .replaceAll("<", "&lt;")
231	      .replaceAll(">", "&gt;")
232	      .replaceAll('"', "&quot;")
233	      .replaceAll("'", "&#39;");
234	  }
235	
236	  function setMonthDefault() {
237	    const now = new Date();
238	    monthPicker.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
239	  }
240	
241	  function selectedYearMonth() {
242	    const [year, month] = (monthPicker.value || "").split("-").map(Number);
243	    return { year, month };
244	  }
245	
246	  function monthLabel() {
247	    const { year, month } = selectedYearMonth();
248	    if (!year || !month) return "this month";
249	    return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
250	  }
251	
252	  function formatDate(iso) {
253	    if (!iso) return "";
254	    const d = new Date(iso);
255	    if (isNaN(d.getTime())) return "";
256	    return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
257	  }
258	
259	  function showBanner(message) {
260	    const banner = document.getElementById("revBanner");
261	    document.getElementById("revBannerText").textContent = message;
262	    banner.style.display = message ? "" : "none";
263	  }
264	
265	  async function loadRole() {
266	    const payload = parseJwtPayload(token);
267	    const role = (
268	      payload["http://schemas.microsoft.com/ws/2008/06/identity/claims/role"] ||
269	      payload.role ||
270	      ""
271	    ).toLowerCase();
272	    isAdmin = role === "admin";
273	    staffPickerWrap.style.display = isAdmin ? "" : "none";
274	    if (isAdmin) await loadReceptionists();
275	  }
276	
277	  // Reuse the KPI dashboard endpoint to enumerate receptionists for the admin picker.
278	  async function loadReceptionists() {
279	    try {
280	      const { year, month } = selectedYearMonth();
281	      const res = await fetch(`${API}/api/receptionist-kpi/dashboard?year=${year}&month=${month}`, {
282	        headers: { Authorization: `Bearer ${token}` },
283	      });
284	      const data = await res.json().catch(() => ({}));
285	      if (!res.ok) return;
286	      const list = data.receptionists || [];
287	      const current = staffPicker.value;
288	      staffPicker.innerHTML = list
289	        .map((s) => `<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`)
290	        .join("");
291	      if (current && list.some((s) => s.id === current)) staffPicker.value = current;
292	    } catch { /* ignore */ }
293	  }
294	
295	  function currentStaffId() {
296	    return isAdmin && staffPicker.value ? staffPicker.value : null;
297	  }
298	
299	  function setSelectedFile(file) {
300	    selectedFile = file || null;
301	    if (selectedFile) {
302	      previewImg.src = URL.createObjectURL(selectedFile);
303	      previewImg.style.display = "";
304	      dropPrompt.style.display = "none";
305	    } else {
306	      previewImg.removeAttribute("src");
307	      previewImg.style.display = "none";
308	      dropPrompt.style.display = "";
309	    }
310	    uploadBtn.disabled = !selectedFile;
311	  }
312	
313	  function wireDropzone() {
314	    dropzone.addEventListener("click", () => fileInput.click());
315	    fileInput.addEventListener("change", () => setSelectedFile(fileInput.files?.[0] || null));
316	    ["dragenter", "dragover"].forEach((evt) =>
317	      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.add("dragover"); }));
318	    ["dragleave", "drop"].forEach((evt) =>
319	      dropzone.addEventListener(evt, (e) => { e.preventDefault(); dropzone.classList.remove("dragover"); }));
320	    dropzone.addEventListener("drop", (e) => {
321	      const file = e.dataTransfer?.files?.[0];
322	      if (file) setSelectedFile(file);
323	    });
324	  }
325	
326	  async function uploadReview() {
327	    if (!selectedFile) return;
328	    const ok = document.getElementById("uploadMsg");
329	    const err = document.getElementById("uploadErr");
330	    ok.style.display = "none";
331	    err.style.display = "none";
332	    uploadBtn.disabled = true;
333	
334	    try {
335	      const { year, month } = selectedYearMonth();
336	      if (!year || !month) throw new Error("Pick a month first.");
337	
338	      const fd = new FormData();
339	      fd.append("file", selectedFile, selectedFile.name);
340	      fd.append("year", String(year));
341	      fd.append("month", String(month));
342	      const staffId = currentStaffId();
343	      if (staffId) fd.append("staffId", staffId);
344	      const reviewerName = document.getElementById("reviewerNameInput").value.trim();
345	      if (reviewerName) fd.append("reviewerName", reviewerName);
346	      const rating = document.getElementById("ratingInput").value;
347	      if (rating) fd.append("rating", rating);
348	      const notes = document.getElementById("notesInput").value.trim();
349	      if (notes) fd.append("notes", notes);
350	
351	      const res = await fetch(`${API}/api/review-uploads`, {
352	        method: "POST",
353	        headers: { Authorization: `Bearer ${token}` },
354	        body: fd,
355	      });
356	      const data = await res.json().catch(() => ({}));
357	      if (!res.ok) throw new Error(data.message || `Upload failed (HTTP ${res.status})`);
358	
359	      ok.style.display = "";
360	      setTimeout(() => { ok.style.display = "none"; }, 2000);
361	      // Reset the form.
362	      setSelectedFile(null);
363	      fileInput.value = "";
364	      document.getElementById("reviewerNameInput").value = "";
365	      document.getElementById("ratingInput").value = "";
366	      document.getElementById("notesInput").value = "";
367	      await loadGallery();
368	    } catch (error) {
369	      err.textContent = error.message || "Upload failed.";
370	      err.style.display = "";
371	    } finally {
372	      uploadBtn.disabled = !selectedFile;
373	    }
374	  }
375	
376	  async function loadGallery() {
377	    const { year, month } = selectedYearMonth();
378	    if (!year || !month) return;
379	    document.getElementById("galleryMonthLabel").textContent = monthLabel();
380	    document.getElementById("uploadMonthLabel").textContent = monthLabel();
381	
382	    const params = new URLSearchParams({ year: String(year), month: String(month) });
383	    const staffId = currentStaffId();
384	    if (staffId) params.set("staffId", staffId);
385	
386	    try {
387	      const res = await fetch(`${API}/api/review-uploads?${params.toString()}`, {
388	        headers: { Authorization: `Bearer ${token}` },
389	      });
390	      const data = await res.json().catch(() => ({}));
391	      if (!res.ok) throw new Error(data.message || `Failed to load reviews (${res.status})`);
392	      renderGallery(data);
393	    } catch (error) {
394	      showBanner(error.message || "Failed to load reviews.");
395	    }
396	  }
397	
398	  function renderGallery(data) {
399	    const grid = document.getElementById("galleryGrid");
400	    const empty = document.getElementById("galleryEmpty");
401	    const items = data.items || [];
402	    document.getElementById("galleryCount").textContent = String(data.count ?? items.length);
403	
404	    if (items.length === 0) {
405	      grid.innerHTML = "";
406	      empty.style.display = "";
407	      return;
408	    }
409	    empty.style.display = "none";
410	
411	    grid.innerHTML = items.map((item) => {
412	      const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
413	      return `
414	        <div class="rev-tile">
415	          <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
416	          <div class="rev-tile-body">
417	            <div class="rev-tile-date">Added ${escapeHtml(formatDate(item.uploadedAt))}</div>
418	            ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
419	            ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
420	            ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
421	            <div class="rev-tile-actions">
422	              <button type="button" class="rev-tile-delete" data-delete-id="${escapeHtml(item.id)}">Delete</button>
423	            </div>
424	          </div>
425	        </div>`;
426	    }).join("");
427	
428	    grid.querySelectorAll("[data-full]").forEach((img) =>
429	      img.addEventListener("click", () => openLightbox(img.dataset.full)));
430	    grid.querySelectorAll("[data-delete-id]").forEach((btn) =>
431	      btn.addEventListener("click", () => deleteReview(btn.dataset.deleteId)));
432	  }
433	
434	  async function deleteReview(id) {
435	    if (!id) return;
436	    if (!confirm("Delete this review upload? This cannot be undone.")) return;
437	    try {
438	      const res = await fetch(`${API}/api/review-uploads/${id}`, {
439	        method: "DELETE",
440	        headers: { Authorization: `Bearer ${token}` },
441	      });
442	      if (!res.ok && res.status !== 204) {
443	        const data = await res.json().catch(() => ({}));
444	        throw new Error(data.message || `Delete failed (${res.status})`);
445	      }
446	      await loadGallery();
447	    } catch (error) {
448	      showBanner(error.message || "Delete failed.");
449	    }
450	  }
