    public async Task<int> CountForMonthAsync(int year, int month, CancellationToken ct = default)
    {
        // Only APPROVED uploads count toward the KPI metric.
        var count = await _uploads.CountDocumentsAsync(
            x => x.Year == year && x.Month == month && x.Status == ReviewApprovalStatus.Approved,
            cancellationToken: ct);
        return (int)count;
    }

    public async Task<ReviewPendingListDto> ListPendingAsync(int? year, int? month, CancellationToken ct = default)
    {
        var filter = Builders<ReviewUpload>.Filter.Eq(x => x.Status, ReviewApprovalStatus.Pending);
        if (year is int y)
            filter &= Builders<ReviewUpload>.Filter.Eq(x => x.Year, y);
        if (month is int m)
        {
            if (m < 1 || m > 12)
                throw new InvalidOperationException("Month must be between 1 and 12.");
            filter &= Builders<ReviewUpload>.Filter.Eq(x => x.Month, m);
        }

        var rows = await _uploads
            .Find(filter)
            .SortByDescending(x => x.UploadedAt)
            .ToListAsync(ct);

        return new ReviewPendingListDto
        {
            Year = year,
            Month = month,
            Count = rows.Count,
            Items = rows.Select(Map).ToList(),
        };
    }

    public async Task<ReviewUploadDto?> ApproveAsync(string id, string approverStaffId, CancellationToken ct = default)
        => await SetStatusAsync(id, ReviewApprovalStatus.Approved, approverStaffId, reason: null, ct);

    public async Task<ReviewUploadDto?> RejectAsync(string id, string approverStaffId, string? reason, CancellationToken ct = default)
        => await SetStatusAsync(id, ReviewApprovalStatus.Rejected, approverStaffId, reason, ct);

    private async Task<ReviewUploadDto?> SetStatusAsync(
        string id, ReviewApprovalStatus status, string? approverStaffId, string? reason, CancellationToken ct)
    {
        var normalizedApprover = string.IsNullOrWhiteSpace(approverStaffId) ? null : approverStaffId;
        var normalizedReason = status == ReviewApprovalStatus.Rejected && !string.IsNullOrWhiteSpace(reason)
            ? reason.Trim()
            : null;

        var update = Builders<ReviewUpload>.Update
            .Set(x => x.Status, status)
            .Set(x => x.ApprovedByStaffId, normalizedApprover)
            .Set(x => x.ApprovedAt, DateTime.UtcNow)
            .Set(x => x.RejectionReason, normalizedReason)
            .Set(x => x.UpdatedAt, DateTime.UtcNow);

        var updated = await _uploads.FindOneAndUpdateAsync<ReviewUpload>(
            x => x.Id == id,
            update,
            new FindOneAndUpdateOptions<ReviewUpload> { ReturnDocument = ReturnDocument.After },
            ct);

        return updated is null ? null : Map(updated);
    }

    private static ReviewUploadDto Map(ReviewUpload x) => new()
    {
        Id = x.Id ?? string.Empty,
        StaffId = x.StaffId,
        StaffName = x.StaffNameSnapshot,
        Year = x.Year,
        Month = x.Month,
        ImageUrl = x.ImageUrl,
        ReviewerName = x.ReviewerName,
        Rating = x.Rating,
        Notes = x.Notes,
        UploadedAt = x.UploadedAt,
        Status = x.Status.ToString(),
        ApprovedByStaffId = x.ApprovedByStaffId,
        ApprovedAt = x.ApprovedAt,
        RejectionReason = x.RejectionReason,
    };
}

