/// <summary>The manager's review queue: pending uploads across all receptionists, optionally by month.</summary>
[HttpGet("pending")]
[Authorize(Roles = "Admin")]
public async Task<IActionResult> Pending(
    [FromQuery] int? year,
    [FromQuery] int? month,
    CancellationToken ct)
{
    try
    {
        var dto = await _reviews.ListPendingAsync(year, month, ct);
        return Ok(dto);
    }
    catch (InvalidOperationException ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>Approve a pending upload so it counts toward the KPI.</summary>
[HttpPost("{id}/approve")]
[Authorize(Roles = "Admin")]
public async Task<IActionResult> Approve(string id, CancellationToken ct)
{
    var dto = await _reviews.ApproveAsync(id, ResolveApproverId(), ct);
    return dto is null ? NotFound(new { message = "Review upload not found." }) : Ok(dto);
}

/// <summary>Reject an upload (with an optional reason) so it does not count toward the KPI.</summary>
[HttpPost("{id}/reject")]
[Authorize(Roles = "Admin")]
public async Task<IActionResult> Reject(string id, [FromBody] ReviewRejectRequestDto? body, CancellationToken ct)
{
    var dto = await _reviews.RejectAsync(id, ResolveApproverId(), body?.Reason, ct);
    return dto is null ? NotFound(new { message = "Review upload not found." }) : Ok(dto);
}

