---
import AdminLayout from "../../layouts/AdminLayout.astro";
---

<AdminLayout title="Review Approvals" activePage="review-approvals">
  <div class="rev-page-shell">
    <div class="rev-page-header">
      <div>
        <div class="page-title">Review Approvals</div>
        <div class="page-subtitle">
          Review each receptionist-uploaded Google review screenshot. Only approved uploads count toward the month's Google Reviews KPI.
        </div>
      </div>
      <div class="rev-page-actions">
        <label class="rev-action-control">
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <rect x="3" y="4" width="18" height="18" rx="2"></rect>
            <line x1="16" y1="2" x2="16" y2="6"></line>
            <line x1="8" y1="2" x2="8" y2="6"></line>
            <line x1="3" y1="10" x2="21" y2="10"></line>
          </svg>
          <input type="month" id="monthPicker" class="rev-inline-input" />
        </label>
        <button type="button" id="clearMonthBtn" class="btn btn-secondary rev-clear-btn">All months</button>
      </div>
    </div>

    <div id="revBanner" class="card rev-banner-card" style="display:none;">
      <div class="card-body" id="revBannerText"></div>
    </div>

    <section class="card rev-gallery-card">
      <div class="card-header">
        <div>
          <div class="card-title">Pending Uploads</div>
          <div class="card-subtitle" id="queueLabel">Loading</div>
        </div>
        <div class="rev-count-pill"><span id="queueCount">0</span> pending</div>
      </div>
      <div class="card-body">
        <div id="queueGrid" class="rev-gallery-grid"></div>
        <div id="queueEmpty" class="rev-empty" style="display:none;">
          No pending review uploads to approve.
        </div>
      </div>
    </section>
  </div>

  <div id="lightbox" class="rev-lightbox" style="display:none;">
    <img id="lightboxImg" src="" alt="Review" />
  </div>
</AdminLayout>

<style is:global>
  .rev-page-shell { display:flex; flex-direction:column; gap:12px; }
  .rev-page-header {
    display:flex; align-items:flex-start; justify-content:space-between;
    gap:16px; flex-wrap:wrap;
  }
  .rev-page-actions { display:flex; gap:10px; flex-wrap:wrap; align-items:center; }
  .rev-action-control {
    display:inline-flex; align-items:center; gap:8px;
    background:var(--color-surface, #fff); border:1px solid var(--color-border, #e2e8f0);
    border-radius:10px; padding:8px 12px; color:var(--color-text-muted, #64748b);
    cursor:pointer;
  }
  .rev-inline-input {
    border:none; background:transparent; color:var(--color-text, #0f172a);
    font:inherit; outline:none; cursor:pointer;
  }
  .rev-clear-btn { padding:8px 12px; }
  .rev-banner-card { border-left:4px solid var(--color-warning, #f59e0b); }

  .rev-count-pill {
    align-self:center; background:var(--color-warning-soft, rgba(245,158,11,.16));
    color:var(--color-warning, #b45309); border-radius:999px; padding:4px 12px;
    font-size:.82rem; font-weight:600; white-space:nowrap;
  }

  .rev-gallery-grid {
    display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:14px;
  }
  .rev-tile {
    border:1px solid var(--color-border, #e2e8f0); border-radius:12px; overflow:hidden;
    display:flex; flex-direction:column; background:var(--color-surface, #fff);
  }
  .rev-tile-img {
    width:100%; aspect-ratio:1/1; object-fit:cover; cursor:zoom-in;
    background:var(--color-surface-muted, #f1f5f9);
  }
  .rev-tile-body { padding:10px 12px; display:flex; flex-direction:column; gap:4px; }
  .rev-tile-date { font-size:.78rem; color:var(--color-text-muted, #64748b); }
  .rev-tile-staff { font-size:.85rem; font-weight:600; color:var(--color-primary, #4f46e5); }
  .rev-tile-reviewer { font-size:.85rem; font-weight:600; color:var(--color-text, #0f172a); }
  .rev-tile-stars { font-size:.8rem; color:#f59e0b; letter-spacing:1px; }
  .rev-tile-notes { font-size:.78rem; color:var(--color-text-muted, #64748b); }

  .rev-approve-actions { display:flex; gap:8px; margin-top:8px; }
  .rev-approve-actions .btn { flex:1; padding:6px 10px; font-size:.82rem; }
  .rev-btn-approve { background:var(--color-success, #16a34a); color:#fff; border:none; }
  .rev-btn-approve:hover { filter:brightness(.95); }
  .rev-btn-reject {
    background:transparent; color:var(--color-danger, #dc2626);
    border:1px solid var(--color-danger, #dc2626);
  }
  .rev-btn-reject:hover { background:var(--color-danger-soft, rgba(220,38,38,.08)); }

  .rev-empty { text-align:center; color:var(--color-text-muted, #94a3b8); padding:30px 10px; }

  .rev-lightbox {
    position:fixed; inset:0; background:rgba(0,0,0,.8); z-index:1000;
    display:grid; place-items:center; padding:24px; cursor:zoom-out;
  }
  .rev-lightbox img { max-width:min(92vw, 900px); max-height:90vh; border-radius:10px; }
</style>

<script>
  const API = import.meta.env.PUBLIC_API_URL;
  const token = localStorage.getItem("token");

  const monthPicker = document.getElementById("monthPicker");
  let filterByMonth = true;

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  }

  function setMonthDefault() {
    const now = new Date();
    monthPicker.value = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  }

  function selectedYearMonth() {
    const [year, month] = (monthPicker.value || "").split("-").map(Number);
    return { year, month };
  }

  function queueLabelText() {
    if (!filterByMonth) return "All months";
    const { year, month } = selectedYearMonth();
    if (!year || !month) return "All months";
    return new Date(year, month - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
  }

  function formatDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
  }

  function showBanner(message) {
    const banner = document.getElementById("revBanner");
    document.getElementById("revBannerText").textContent = message || "";
    banner.style.display = message ? "" : "none";
  }

  async function loadQueue() {
    document.getElementById("queueLabel").textContent = queueLabelText();
    const params = new URLSearchParams();
    if (filterByMonth) {
      const { year, month } = selectedYearMonth();
      if (year && month) { params.set("year", String(year)); params.set("month", String(month)); }
    }
    try {
      const res = await fetch(`${API}/api/review-uploads/pending?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.message || `Failed to load pending reviews (${res.status})`);
      showBanner("");
      renderQueue(data);
    } catch (error) {
      showBanner(error.message || "Failed to load pending reviews.");
    }
  }

  function renderQueue(data) {
    const grid = document.getElementById("queueGrid");
    const empty = document.getElementById("queueEmpty");
    const items = data.items || [];
    document.getElementById("queueCount").textContent = String(data.count ?? items.length);

    if (items.length === 0) {
      grid.innerHTML = "";
      empty.style.display = "";
      return;
    }
    empty.style.display = "none";

    grid.innerHTML = items.map((item) => {
      const stars = item.rating ? "★".repeat(item.rating) + "☆".repeat(5 - item.rating) : "";
      const period = new Date(item.year, item.month - 1, 1)
        .toLocaleDateString(undefined, { month: "short", year: "numeric" });
      return `
        <div class="rev-tile">
          <img class="rev-tile-img" src="${escapeHtml(item.imageUrl)}" alt="Review" loading="lazy" data-full="${escapeHtml(item.imageUrl)}" />
          <div class="rev-tile-body">
            <div class="rev-tile-staff">${escapeHtml(item.staffName || "Receptionist")}</div>
            <div class="rev-tile-date">Added ${escapeHtml(formatDate(item.uploadedAt))} · ${escapeHtml(period)}</div>
            ${item.reviewerName ? `<div class="rev-tile-reviewer">${escapeHtml(item.reviewerName)}</div>` : ""}
            ${stars ? `<div class="rev-tile-stars">${stars}</div>` : ""}
            ${item.notes ? `<div class="rev-tile-notes">${escapeHtml(item.notes)}</div>` : ""}
            <div class="rev-approve-actions">
              <button type="button" class="btn rev-btn-approve" data-approve-id="${escapeHtml(item.id)}">Approve</button>
              <button type="button" class="btn rev-btn-reject" data-reject-id="${escapeHtml(item.id)}">Reject</button>
            </div>
          </div>
        </div>`;
    }).join("");

    grid.querySelectorAll("[data-full]").forEach((img) =>
      img.addEventListener("click", () => openLightbox(img.dataset.full)));
    grid.querySelectorAll("[data-approve-id]").forEach((btn) =>
      btn.addEventListener("click", () => decide(btn.dataset.approveId, "approve")));
    grid.querySelectorAll("[data-reject-id]").forEach((btn) =>
      btn.addEventListener("click", () => decide(btn.dataset.rejectId, "reject")));
  }

  async function decide(id, action) {
    if (!id) return;
    let body;
    if (action === "reject") {
      const reason = prompt("Optional reason for rejecting this review:", "");
      if (reason === null) return; // cancelled
      body = JSON.stringify({ reason });
    }
    try {
      const res = await fetch(`${API}/api/review-uploads/${id}/${action}`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: body ?? "{}",
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.message || `${action} failed (${res.status})`);
      }
      await loadQueue();
    } catch (error) {
      showBanner(error.message || `${action} failed.`);
    }
  }

  function openLightbox(url) {
    const box = document.getElementById("lightbox");
    document.getElementById("lightboxImg").src = url;
    box.style.display = "grid";
  }
  document.getElementById("lightbox").addEventListener("click", (e) => {
    e.currentTarget.style.display = "none";
    document.getElementById("lightboxImg").removeAttribute("src");
  });

  monthPicker.addEventListener("change", () => { filterByMonth = true; loadQueue(); });
  document.getElementById("clearMonthBtn").addEventListener("click", () => { filterByMonth = false; loadQueue(); });

  setMonthDefault();
  (async function init() {
    try {
      await loadQueue();
    } catch (error) {
      showBanner(error.message || "Failed to load review approvals page.");
    }
  })();
</script>
